-- Sixth batch of explicitly labelled supplemental study outlines for MBH histology.
-- Idempotent: existing answers are never overwritten.
with supplemental_answers(id, answer) as (
  values
  ('1be6f3ed-62a6-5b74-8f8e-6ddfb45fe8ff', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гемопоэтические стволовые клетки способны к самообновлению и образованию всех линий крови; полустволовые и более ограниченные предшественники постепенно утрачивают потенциал и проходят пролиферацию/созревание. Тромбоцитопоэз идёт в красном костном мозге: мегакариобласты увеличиваются, проходят эндомитоз и становятся полиплоидными мегакариоцитами; фрагменты их цитоплазмы отделяются в синусоиды и становятся тромбоцитами. Тромбоциты участвуют в первичном гемостазе.'),
  ('6737eff6-f6de-5079-ad9c-2736d1118fa4', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Митохондрии имеют наружную и внутреннюю мембраны, кристы, межмембранное пространство и матрикс с ферментами, митохондриальной ДНК и рибосомами. Основная функция — синтез АТФ при окислительном фосфорилировании; также участвуют в обмене метаболитов, регуляции Ca2+ и апоптоза. В цитоплазме находятся органеллы и включения; митохондрии особенно многочисленны в клетках с высокой потребностью в энергии.'),
  ('d0ff9c3d-0aaf-5398-8792-b5fd993e98da', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эндоплазматическая сеть — система мембранных цистерн и канальцев. Гранулярная ЭПС несёт рибосомы и синтезирует белки секреции, мембран и лизосом; гладкая ЭПС участвует в синтезе липидов, детоксикации и депонировании Ca2+. Рибосомы — комплексы рРНК и белков, состоящие из большой и малой субъединиц; они транслируют мРНК в полипептид. Свободные рибосомы преимущественно синтезируют цитозольные белки, связанные с ЭПС — секретируемые и мембранные.'),
  ('58453e9c-43ba-5f21-a186-22e1d199b07e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Вены классифицируют по калибру и строению стенки; по сравнению с артериями их просвет обычно шире, стенка тоньше, а медия слабее развита. Интима включает эндотелий; медия содержит гладкие миоциты и соединительнотканные элементы; адвентиция часто наиболее выражена и в крупных венах может содержать продольные пучки гладких миоцитов. Клапаны — складки интимы, препятствующие обратному току крови в определённых венах. Строение связано с низким давлением и ёмкостной функцией вен.'),
  ('cb067756-bfd8-5ac1-a8fc-eff7ec529ca3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Красный костный мозг содержит кроветворные клетки разных стадий, синусоидные капилляры, макрофаги, ретикулярные стромальные клетки и жировые клетки. Строма обеспечивает сигнальную нишу и поддержку созревания. Гранулоцитопоэз включает миелобласт, промиелоцит, миелоцит, метамиелоцит, палочкоядерную и сегментоядерную формы; моноцитопоэз проходит от монобласта через промоноцит к моноциту крови, который может дифференцироваться в тканевой макрофаг.'),
  ('82615022-ba10-5201-8fff-fa5af3b1c315', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Вегетативные ганглии содержат тела нейронов, синапсы, глиальные клетки и соединительнотканную капсулу. В паравертебральных и превертебральных ганглиях симпатической системы нейроны обычно мультиполярные; в терминальных/интрамуральных парасимпатических ганглиях тела нейронов расположены близко к органу или в его стенке. Сателлитные глиоциты окружают тела нейронов. Преганглионарные волокна образуют синапсы с постганглионарными клетками, а постганглионарные аксоны идут к эффекторам.'),
  ('a0e8702f-4e9b-5fcf-944a-994ee57a44d6', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Автономная нервная система регулирует гладкие мышцы, сердце и железы; включает симпатический, парасимпатический и энтеральный отделы. В типичной эфферентной дуге преганглионарный нейрон расположен в ЦНС, его аксон переключается в вегетативном ганглии на постганглионарный нейрон, который иннервирует орган. Симпатические центры имеют тораколюмбальное расположение, парасимпатические — краниосакральное. Передача в ганглии обычно холинергическая; в органах медиаторы зависят от отдела и мишени.'),
  ('1e0a7925-f49f-56bf-a13f-aa6d036f5e6b', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Микротрубочки состоят из α/β-тубулина, формируют цитоскелет, веретено деления, реснички и жгутики; центриоли организованы как цилиндры из девяти триплетов микротрубочек и входят в состав центросомы/базальных телец. Подвижные реснички и жгутики имеют аксонему 9+2, а базальное тельце — девять триплетов; динеин обеспечивает скольжение микротрубочек и изгиб. Эти структуры обеспечивают внутриклеточный транспорт, расхождение хромосом и движение жидкости или клетки.'),
  ('d65e7d54-09f1-5ca7-8a8c-5a00421fcd11', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Основные компоненты ядра: ядерная оболочка с порами, хроматин, ядрышко и кариоплазма. Оболочка отделяет геном от цитоплазмы и регулирует транспорт РНК и белков. Хроматин — ДНК с гистонами и другими белками; его упаковка регулирует доступность генов. Ядрышко обеспечивает синтез рРНК и начальную сборку рибосомных субъединиц. Ядро контролирует транскрипцию, репликацию ДНК и передачу наследственной информации.'),
  ('a9b8ae79-98c0-59d6-88f5-bd155e00b9d5', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Плоидность отражает наборы хромосом, а содержание ДНК изменяется в клеточном цикле: после S-фазы ДНК удваивается, но плоидность до разделения ядра остаётся прежней. Эндоредупликация — повторная репликация ДНК без обычного митоза/цитокинеза, приводящая к полиплоидии; эндомитоз может приводить к полиплоидным клеткам, например мегакариоцитам. Двуядерные клетки могут возникать при кариокинезе без цитокинеза; многоядерные симпласты — при слиянии клеток.'),
  ('19f4cc93-fd3c-5a44-86fc-ed1dd16d8d31', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Артерии классифицируют на эластические, мышечные и переходные; их стенка включает интиму, медию и адвентицию. В аорте медия содержит многочисленные эластические пластинки, которые растягиваются при систоле и поддерживают кровоток в диастолу. В артериях мышечного типа преобладают гладкие миоциты, регулирующие сопротивление и распределение крови. С возрастом возможны утолщение интимы, изменения эластических волокон и повышение жёсткости стенки; степень изменений зависит от физиологии и патологии.'),
  ('9b62f93f-cd1f-598c-838f-0de9d56dd29b', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Вены бывают мелкими, средними и крупными; по особенностям строения выделяют мышечные и безмышечные варианты. У вен мышечного типа медия содержит гладкие миоциты, а адвентиция нередко преобладает; в крупных венах адвентиция может содержать продольные мышечные пучки. Лимфатические капилляры начинаются слепо, имеют тонкую стенку и перекрывающиеся эндотелиальные края, пропускающие тканевую жидкость. Лимфатические сосуды имеют клапаны и проводят лимфу к узлам и далее в венозное русло.'),
  ('0dab45c2-504f-54e9-831e-c360c721fe15', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гемопоэз начинается в эмбриогенезе внеэмбрионально, затем происходит в печени и селезёнке плода, а после рождения преимущественно в красном костном мозге. Гемопоэтические стволовые клетки самообновляются и дают начало мультипотентным, затем ограниченным предшественникам и зрелым клеткам крови. Строма красного костного мозга включает ретикулярные клетки, макрофаги, синусоидные сосуды и внеклеточный матрикс; она поддерживает созревание клеток. Гранулоцитопоэз и моноцитопоэз проходят стадии пролиферации, созревания и выхода зрелых клеток в кровь.'),
  ('fd45f5a8-4996-5f58-b9ee-ebd8a0601f97', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Воздухоносные пути включают полость носа, глотку, гортань, трахею и бронхи. В трахее слизистая покрыта однослойным многорядным реснитчатым эпителием с бокаловидными клетками; под ним находятся собственная пластинка, подслизистая с железами, С-образные гиалиновые хрящевые кольца и адвентиция. В бронхах хрящ образует пластинки, гладкая мышца выражена сильнее, а эпителий постепенно становится ниже; реснички и слизь обеспечивают мукоцилиарный клиренс.'),
  ('b14ad3ae-475c-5885-967d-d1a6bff0b290', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Подъязычная слюнная железа — сложная разветвлённая смешанная железа с преобладанием слизистых концевых отделов; серозные клетки могут образовывать полулуния. Слизистые клетки имеют светлую пенистую цитоплазму и уплощённые базальные ядра. В протоковой системе вставочные и исчерченные отделы обычно развиты слабее, чем в околоушной и поднижнечелюстной железах. Секрет богат муцинами и обеспечивает смазывание слизистой полости рта.'),
  ('375f70a1-47ff-5316-b902-06bf0d3d91c5', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Комплекс Гольджи состоит из полярных стопок уплощённых цистерн и пузырьков: cis-сторона принимает материал из ЭПС, trans-сторона сортирует и отправляет его. Здесь белки и липиды модифицируются (например, гликозилируются), упаковываются для секреции, мембран или лизосом. Комплекс Гольджи участвует в образовании первичных лизосом и секреторных гранул.'),
  ('8b7f3f29-ed81-5658-b62b-f5b703b62272', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Околоушная железа преимущественно серозная, поднижнечелюстная — смешанная с преобладанием серозных отделов, подъязычная — смешанная с преобладанием слизистых. Концевые отделы соединяются с системой протоков; исчерченные протоки активно изменяют состав слюны. Регенерация слюнных желез ограничена и зависит от сохранности протоковых/прогениторных клеток и стромы; после повреждения возможны атрофия и фиброз. При сравнении препаратов оценивают тип секрета, просветы отделов, протоки и жировые клетки.'),
  ('f9b78ac5-dbb1-525e-975e-279b08f79310', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Ядро окружено двойной оболочкой с ядерными порами, содержит кариоплазму, хроматин и ядрышко. Хроматин включает ДНК с белками; эухроматин обычно менее конденсирован и транскрипционно активнее, гетерохроматин плотнее. Ядрышко участвует в синтезе рРНК и сборке субъединиц рибосом. Репродукция клеток чаще происходит митозом, при котором геном распределяется между дочерними клетками; некоторые клетки выходят в G0 и не делятся регулярно.'),
  ('45134cb6-f774-515c-8724-251e34048506', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Альвеолярный отросток челюсти содержит зубные альвеолы, компактные костные пластинки, губчатую кость и периодонтальную связку, которая соединяет цемент корня с альвеолярной костью. Поддерживающий аппарат зуба включает десну, цемент, периодонт и альвеолярную кость. При жевательной нагрузке происходит ремоделирование: остеокласты резорбируют кость в зонах давления, остеобласты формируют её в зонах натяжения. Возраст, воспаление и изменение нагрузки влияют на высоту альвеолярной кости и состояние периодонта.'),
  ('bb9b80f1-a957-5063-aa69-f7491c1a7b09', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Поднижнечелюстная слюнная железа — сложная разветвлённая трубчато-альвеолярная смешанная железа с преобладанием серозных отделов; слизистые отделы могут иметь серозные полулуния. Концевые отделы выделяют белково-слизистую слюну. В протоковой системе различают вставочные, исчерченные и более крупные выводные протоки; исчерченные протоки модифицируют электролитный состав секрета. Железистая паренхима развивается из эпителиальных зачатков полости рта, строма — из окружающей мезенхимы.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
